using System;using System.Linq;using System.Text;using System.Security.Cryptography;using System.Collections.Generic;using System.Web.Script.Serialization;
using Autodesk.AutoCAD.DatabaseServices;
public static class NativeTextStylesV1 {
 static readonly JavaScriptSerializer J=new JavaScriptSerializer{MaxJsonLength=10000000};
 static void Need(bool b,string s){if(!b)throw new InvalidOperationException(s);}
 static object Props(TextStyleTableRecord s){var f=s.Font;var extra=new SortedDictionary<string,object>();foreach(var n in new[]{"Annotative","PaperOrientation","PriorSize"}){var p=s.GetType().GetProperty(n);if(p!=null)extra[n]=Convert.ToString(p.GetValue(s,null),System.Globalization.CultureInfo.InvariantCulture);}return new{font_file=s.FileName,big_font_file=s.BigFontFileName,text_size=s.TextSize,width_factor=s.XScale,oblique_angle=s.ObliquingAngle,vertical=s.IsVertical,shape_file=s.IsShapeFile,flags=s.FlagBits,font=new{typeface=f.TypeFace,bold=f.Bold,italic=f.Italic,character_set=f.CharacterSet,pitch_and_family=f.PitchAndFamily},extra=extra};}
 static string Key(TextStyleTableRecord s){return J.Serialize(Props(s));}
 static string Suffix(string s){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(Encoding.UTF8.GetBytes(s))).Replace("-","").Substring(0,10);}
 public static object Read(Database db,string[] names){var rows=new List<object>();using(var tr=db.TransactionManager.StartTransaction()){var table=(TextStyleTable)tr.GetObject(db.TextStyleTableId,OpenMode.ForRead);var selected=names==null||names.Length==0?table.Cast<Autodesk.AutoCAD.DatabaseServices.ObjectId>().Select(id=>((TextStyleTableRecord)tr.GetObject(id,OpenMode.ForRead)).Name).ToArray():names;foreach(var name in selected){if(!table.Has(name)){rows.Add(new{name,found=false});continue;}var s=(TextStyleTableRecord)tr.GetObject(table[name],OpenMode.ForRead);rows.Add(new{name=s.Name,found=true,handle=s.Handle.ToString(),dependent=s.IsDependent,has_extension_dictionary=!s.ExtensionDictionary.IsNull,properties=Props(s)});} }return rows;}
 public static Dictionary<string,string> Snapshot(Database db,bool localOnly=false){var result=new Dictionary<string,string>();using(var tr=db.TransactionManager.StartTransaction()){var table=(TextStyleTable)tr.GetObject(db.TextStyleTableId,OpenMode.ForRead);foreach(Autodesk.AutoCAD.DatabaseServices.ObjectId id in table){var s=(TextStyleTableRecord)tr.GetObject(id,OpenMode.ForRead);if(localOnly&&s.IsDependent)continue;result.Add(s.Handle.ToString(),J.Serialize(new{name=s.Name,properties=Props(s)}));}}return result;}
 public static void Preserve(Database db,Dictionary<string,string> old){var after=Snapshot(db);foreach(var p in old)Need(after.ContainsKey(p.Key)&&after[p.Key]==p.Value,"EXISTING_TEXT_STYLE_CHANGED:"+p.Key);}
 public static object Import(Database target,Database source,string[] names,Action mutate){var touched=new HashSet<string>();ObjectEventHandler changed=(sender,e)=>{if(e.DBObject is Entity)touched.Add(e.DBObject.Handle.ToString());};ObjectErasedEventHandler erased=(sender,e)=>{if(e.Erased&&e.DBObject is Entity)touched.Add(e.DBObject.Handle.ToString());};target.ObjectModified+=changed;target.ObjectAppended+=changed;target.ObjectErased+=erased;try{var result=ImportCore(target,source,names,mutate);Need(touched.Count==0,"STYLE_IMPORT_TOUCHED_ENTITY:"+String.Join(",",touched));return result;}finally{target.ObjectModified-=changed;target.ObjectAppended-=changed;target.ObjectErased-=erased;}}
 static object ImportCore(Database target,Database source,string[] names,Action mutate){Need(names!=null&&names.Length>0&&names.Distinct(StringComparer.OrdinalIgnoreCase).Count()==names.Length,"UNIQUE_SOURCE_STYLES_REQUIRED");var old=Snapshot(target);var rows=new List<object>();
  foreach(var name in names){Autodesk.AutoCAD.DatabaseServices.ObjectId srcId;string key,sourceName;using(var tr=source.TransactionManager.StartTransaction()){var st=(TextStyleTable)tr.GetObject(source.TextStyleTableId,OpenMode.ForRead);Need(st.Has(name),"SOURCE_TEXT_STYLE_MISSING:"+name);var s=(TextStyleTableRecord)tr.GetObject(st[name],OpenMode.ForRead);Need(!s.IsDependent,"DEPENDENT_STYLE_NOT_SUPPORTED");srcId=s.ObjectId;sourceName=s.Name;key=Key(s);}
   string equivalent=null,desired=sourceName;using(var tr=target.TransactionManager.StartTransaction()){var tt=(TextStyleTable)tr.GetObject(target.TextStyleTableId,OpenMode.ForRead);foreach(Autodesk.AutoCAD.DatabaseServices.ObjectId id in tt){var t=(TextStyleTableRecord)tr.GetObject(id,OpenMode.ForRead);if(!t.IsDependent&&Key(t)==key){equivalent=t.Name;break;}}if(tt.Has(desired))desired=sourceName+"_Imported_"+Suffix(key);Need(equivalent!=null||!tt.Has(desired),"IMPORT_NAME_COLLISION:"+desired);}
   if(equivalent!=null){rows.Add(new{source=sourceName,target=equivalent,created=false,equivalence="native_render_properties"});continue;}
   mutate();var map=new IdMapping();source.WblockCloneObjects(new ObjectIdCollection(new[]{srcId}),target.TextStyleTableId,map,DuplicateRecordCloning.MangleName,false);var targetId=map[srcId].Value;
   using(var tr=target.TransactionManager.StartTransaction()){var t=(TextStyleTableRecord)tr.GetObject(targetId,OpenMode.ForWrite);t.Name=desired;Need(Key(t)==key,"CLONED_STYLE_PROPERTIES_MISMATCH");tr.Commit();}
   rows.Add(new{source=sourceName,target=desired,created=true,equivalence="native_render_properties"});
  }Preserve(target,old);return new{operation="text_style_import",styles=rows,existing_styles_preserved=true,entities_unchanged=true};
 }
}
